        address[12] memory targetToken = [
            address(usdt),
            address(sol),
            address(AVAX),
            address(babydoge),
            address(FOLKI),
            address(ATOM),
            address(TLOS),
            address(IOTX),
            address(linch),
            address(link),
            address(btcb),
            address(eth)
        ];

